/**
 * Web-ready brand assets.
 *
 * The files in public/brand and public/media are generated by scripts/build-web-assets.sh from the
 * owner-supplied originals in docs/05-CONTENT-AND-ASSETS/assets/ (never modified). They are plain
 * public files, not build-time imports: the AVIF variants cannot be imported by the current
 * Turbopack build, and a hand-written <picture> gives exact control over the bytes that ship.
 *
 * Intrinsic sizes are recorded here because public files carry no build-time metadata. They match
 * the output of scripts/build-web-assets.sh; tests/studio/web-assets.test.ts fails if a file is
 * missing or its real dimensions drift from these values.
 *
 * Rules from docs/01-BRAND-IDENTITY/CONTENT_GUIDELINES.md:
 * - the AN mark is the only logo used in the nav (never the full lockup, never an opaque JPG);
 * - the portrait is used in the hero only and is never cropped through the face.
 */

/** Trimmed AN monogram (174x112): transparent field, opaque dark artwork, 1px white stroke. */
export const anMark = { src: "/brand/an-mark.webp", width: 174, height: 112 } as const;

/** Full "AKBAR / NAWASUNDA / RMX" lockup (400x303). Footer, EPK and history sections only. */
export const lockup = { src: "/brand/lockup.webp", width: 400, height: 303 } as const;

export const portraitAlt =
  "Akbar Nawasunda in a dark AN jacket, lit by a purple rim light in a dim studio";

/**
 * Official portrait in three widths. AVIF and WebP are offered through <picture>, so a browser
 * downloads one file only. The largest WebP is 146 KB, inside the 150 KB LCP budget.
 */
export const portraitSources = [
  { width: 480, height: 600, avif: "/media/portrait-480.avif", webp: "/media/portrait-480.webp" },
  { width: 720, height: 899, avif: "/media/portrait-720.avif", webp: "/media/portrait-720.webp" },
  { width: 960, height: 1199, avif: "/media/portrait-960.avif", webp: "/media/portrait-960.webp" },
] as const;

/** The widest variant. Its aspect ratio is the one the hero reserves before the image loads. */
export const portraitSize = { width: 960, height: 1199 } as const;

/**
 * Square stage frame for the visual-archive band below the fold. Decorative: the artwork carries no
 * information the copy does not, so it is rendered with an empty alt.
 */
export const stageFrame = {
  width: 700,
  height: 700,
  avif: "/media/stage-700.avif",
  webp: "/media/stage-700.webp",
  /** Smaller copy for the archive tile; the lightbox uses the 700px pair above. */
  thumb: { width: 480, height: 480, webp: "/media/stage-480.webp", avif: "/media/stage-480.avif" },
} as const;
